/bin/bash -lc "python - <<'PY'
import generate as g,numpy as np
s=np.load('source_pixels.npz')['rgb'];tr=g.source_tracks(s)
for j in range(2):
 u=g.unproject(tr[j][:,0])
 print(j,'first30 u',np.round(u[:32],2))
 print('v range',np.round(np.diff(u[:32]),2))
 if j==0:print('precontact fit',np.polyfit(np.arange(4,15),u[4:15],1))
 else:print('postcontact fit',np.polyfit(np.arange(16,28),u[16:28],1))
p=g.clean_plate(s,tr)
for i in range(3):
 sp=g.sprite(s,p,tr[i][0],0)
 d=sp['delta'];print('SPRITE',i,'dims',d.shape,'origin',sp['origin'],'minmax',d.min(),d.max(),'active',np.sum(abs(d).max(2)>15))
 print('bounds',end=' ');yy,xx=np.where(abs(d).max(2)>15);print(xx.min(),yy.min(),xx.max(),yy.max())
 # numeric residual occupancy map
 for row in np.max(abs(d),axis=2):print(''.join(' ' if v<5 else '.' if v<15 else '+' if v<40 else 'o' if v<80 else '#' for v in row))
f=np.load('pixels.npz')['pixels'].transpose(2,0,1)
f=np.stack([(f>>16)&255,(f>>8)&255,f&255],-1).astype('uint8')
for t in [14,15,16,18,24,36,48,65,75,95]:
 a=f[t].astype(float)
 print('FRAME',t)
 for j in [0,1,2]:
  if j==0:mask=(a[:,:,2]>a[:,:,0]*1.4)&(a[:,:,2]>a[:,:,1]*1.12)&(a[:,:,2]>70)
  elif j==1:mask=(a[:,:,0]>a[:,:,1]*1.45)&(a[:,:,0]>a[:,:,2]*1.6)
  else:mask=(a[:,:,0]>230)&(a[:,:,1]>215)&(a[:,:,2]-a[:,:,0]<12)
  mask[:50]=0;mask[:,180:]=0;mask[:,:50]=0;mask[110:]=0
  yy,xx=np.where(mask);print(j,len(xx),np.round([xx.mean(),yy.mean()],2))
print('Artifacts:',f.shape)
PY"
